import torch, torch.nn.functional as F
def moe_forward(x, gate, experts, S):
    # x:[B,d], gate:[B,N], experts:list of fns
    logits = gate(x)
    topk = logits.topk(k=2, dim=-1)
    out = torch.zeros_like(x)
    for idx, w in zip(topk.indices.T, topk.values.T):
        for i, ei in enumerate(idx):
            if int(ei) in S:
                out[i] += w[i] * experts[int(ei)](x[i])
    return out, topk
